import { useEffect, useState } from 'react';
import { Chart } from 'primereact/chart';
import { getMetrics } from '../services/api';

const metricLabels = {
  'Температура, °C': 'Температура (°C)',
  'Вологість, %': 'Вологість (%)',
  'Освітлення, lx': 'Освітлення (lx)',
  'Тиск, гПа': 'Тиск (гПа)',
  'Якість повітря (PM2.5, мкг/м³)': 'Якість повітря (PM2.5, мкг/м³)',
  'CO₂ (ppm)': 'CO₂ (ppm)',
  'Швидкість вітру (м/с)': 'Швидкість вітру (м/с)',
  'Рівень шуму (дБ)': 'Рівень шуму (дБ)',
  'Заряд батареї (%)': 'Заряд батареї (%)',
  // додай інші типи, якщо потрібно
};

export default function MetricsChart({ deviceId, dateRange, metricTypes }) {
  const [metricsByType, setMetricsByType] = useState({});

useEffect(() => {
  if (!deviceId) return;

  const params = { deviceId };

  if (dateRange?.[0] && dateRange?.[1]) {
    params.stime = dateRange[0].toISOString();
    params.etime = dateRange[1].toISOString();
  }

  if (metricTypes?.length) {
    params.types = metricTypes;
  }

  getMetrics(params).then((metrics) => {
    console.log('Отримані метрики:', metrics); // Для дебагу
    const grouped = {};
    for (const metric of metrics) {
      const { type_of_metrics: type, value_of_metrics: value, time } = metric;
      if (!grouped[type]) grouped[type] = { labels: [], data: [] };
      grouped[type].labels.push(new Date(time).toLocaleString('uk-UA', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }));
      grouped[type].data.push(parseFloat(value));
    }
    setMetricsByType(grouped);
  });
}, [deviceId, dateRange, metricTypes]);

  if (!deviceId) {
    return <div className="card">Виберіть пристрій для перегляду метрик</div>;
  }

  if (Object.keys(metricsByType).length === 0) {
    return <div className="card">Немає даних для відображення</div>;
  }

  return (
    <div className="grid">
      {Object.entries(metricsByType).map(([type, { labels, data }]) => (
        <div className="col-12 md:col-6" key={type}>
          <div className="card">
            <h4>{metricLabels[type] || type}</h4>
            <Chart
              type="line"
              data={{
                labels,
                datasets: [{
                  label: metricLabels[type] || type,
                  data,
                  borderColor: '#42A5F5',
                  fill: false,
                }],
              }}
              options={{
                responsive: true,
                plugins: {
                  legend: { position: 'top' },
                },
              }}
            />
          </div>
        </div>
      ))}
    </div>
  );
}
